export function getMockAssistantReply(prompt: string): string {
  const topic = prompt.trim().replace(/[.!?]+$/, "");

  return [
    `I can help you think through ${topic || "that"}.`,
    "",
    "This is a local UI preview, so replies are illustrative and aren't generated by an AI service yet. When your backend is ready, connect this flow through the typed API client in `src/lib/api`.",
  ].join("\n");
}
